# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import round_spans, rounded_labels


class RoundingTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        result = round_spans([Span(547, 1028)], 15)
        self.assertEqual(result, [Span(540, 1035)])

    def test_halves_round_up(self):
        result = round_spans([Span(7, 22)], 15)
        self.assertEqual(result, [Span(0, 15)])

    def test_label(self):
        spans = [Span(540, 1035)]
        self.assertEqual(
            rounded_labels(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)


if __name__ == "__main__":
    unittest.main()
